package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import com.creatorhub.model.Collaboration; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import javax.servlet.*; import java.io.*; @WebServlet("/create") public class CreateServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!ok(r)){s.sendRedirect(r.getContextPath()+"/?error=Login+required");return;}r.getRequestDispatcher("/WEB-INF/jsp/create.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{if(!ok(r)){s.sendRedirect(r.getContextPath()+"/?error=Login+required");return;}try{Collaboration c=new Collaboration();c.setCreatorId((Integer)r.getSession().getAttribute("studentId"));c.setTitle(r.getParameter("title"));c.setCategory(r.getParameter("category"));c.setDescription(r.getParameter("description"));c.setRequiredRole(r.getParameter("requiredRole"));new CreatorDAO().create(c);s.sendRedirect(r.getContextPath()+"/dashboard?message=Collaboration+created");}catch(Exception e){throw new IOException(e);}}private boolean ok(HttpServletRequest r){return r.getSession(false)!=null&&r.getSession(false).getAttribute("studentId")!=null;}}
